"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7429],{37429:n=>{n.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"06-strategiya","title":"Урок 06. Стратегия: Архитектура спокойного портфеля","sourceFingerprint":"800a269023d03d468cf990a95a33955fc04ed298fe7ec35bfbf24fdf044f0c1d","blocks":[{"id":"b001","markdown":"*MakeCash Книга \xb7 Учебный блок 6*  \\n*Время чтения: ~7 минут*"},{"id":"b002","markdown":"# Архитектура спокойного портфеля: почему хладнокровие побеждает суету"},{"id":"b003","markdown":"> \xabБогатство на фондовом рынке формируется не скоростью кликов в приложении, а способностью годами не мешать сложному проценту делать свою работу\xbb."},{"id":"b004","markdown":"## 1. Суровая арифметика частного трейдинга: уроки статистики"},{"id":"b005","markdown":"В середине 2026 года регулятор (Банк России) подвёл итоги трёхлетнего периода (2023–2025 гг.), проанализировав фактическую доходность розничных брокерских счетов объёмом от 10 000 до 10 000 000 ₽. Итог оказался обескураживающим: **среднестатистический розничный инвестор фиксировал всего 2,9% годовых**."},{"id":"b006","markdown":"Для сопоставления: самый консервативный инструмент — стандартный банковский депозит — принёс за то же время в среднем **13,7% годовых**."},{"id":"b007","markdown":"Срез по категориям трейдеров показал следующее распределение:\\n* **41% участников** зафиксировали скромный результат в диапазоне **от 0,1% до 6,7% в год**;\\n* **13% счетов** показали прирост на уровне **от 6,7% до 17,2%**;\\n* **Лишь 9% инвесторов** сумели перешагнуть планку в **17,2% годовых**;\\n* **Около 37% портфелей** балансировали около нулевой отметки либо вовсе ушли в глубокую просадку."},{"id":"b008","markdown":"Главным разрушителем капитала ожидаемо выступили спекулятивные сделки с деривативами (фьючерсами и опционами) и попытки угадать краткосрочные колебания."},{"id":"b009","markdown":"На противоположном полюсе оказались держатели паёв биржевых и паевых фондов: их средний темп прироста составил **17,9% годовых**. Безусловно, отрезок 2023–2025 годов характеризовался циклом жёсткой денежно-кредитной политики, когда фонды денежного рынка (такие как LQDT) приносили рекордный доход на фоне высокой ключевой ставки. Однако разрыв между **2,9%** у активных торговцев и **17,9%** у пассивных владельцев фондов фундаментален: его невозможно списать на простое везение."},{"id":"b010","markdown":"## 2. \xabПоведенческий разрыв\xbb: почему фонд растёт, а инвестор теряет"},{"id":"b011","markdown":"Биржевой фонд функционирует по принципу коллективного траста. Капиталы сотен тысяч вкладчиков стекаются в единый пул, на который профессиональный управляющий строго по регламенту приобретает целевой набор активов: государственные облигации, акции широкого индекса или физическое золото. Каждый участник владеет паем — юридически обособленной микродолей общего котла. Активы фонда изолированы от баланса управляющей компании, а сделки совершаются за секунды на биржевом терминале."},{"id":"b012","markdown":"Но возникает парадокс: сам фонд за десятилетие может показать выдающуюся доходность, а средний человек, инвестирующий в него, останется в убытке."},{"id":"b013","markdown":"Аналитическая корпорация *Morningstar* регулярно выпускает исследование *\xabMind the Gap\xbb*, сопоставляя чистую доходность фондов с фактическим финансовым результатом их клиентов:"},{"id":"b014","markdown":"* На десятилетнем горизонте до конца 2024 года американские частные инвесторы недополучали в среднем **1,2 процентного пункта ежегодно** по сравнению с доходностью купленных ими фондов.\\n* Из-за неудачного тайминга люди добровольно сжигали около **15% совокупной прибыли**."},{"id":"b015","markdown":"### Анатомия типичной эмоциональной ошибки\\n1. **Фонд взлетает на 30% за год.** Отовсюду звучат восторженные прогнозы, графики сияют зелёным. Массовый розничный инвестор поддается стадному чувству и вливает сбережения на самом ценовом пике.\\n2. **Наступает рыночная коррекция на 20%.** Начинается паника. Не выдержав стресса от просадки, вкладчик сбрасывает паи в убыток.\\n3. **Итог цикла:** инструмент фундаментально вырос, но эмоциональный владелец остался с зафиксированным минусом."},{"id":"b016","markdown":"> \uD83D\uDCCC **Важное наблюдение Morningstar:** В сбалансированных индексных фондах, где пропорция акций и бондов удерживается автоматически, этот разрыв сводится к нулю. Когда правила распределения долей зафиксированы заранее, у инвестора нет соблазна судорожно реагировать на заголовки новостей."},{"id":"b017","markdown":"Попытка еженедельно перекраивать структуру активов напоминает попытку начинающего агронома каждое утро выдёргивать из земли саженец, чтобы проверить, окрепла ли корневая система. Растение от такой заботы неизбежно погибнет. С портфелем происходит ровно то же самое."},{"id":"b018","markdown":"## 3. Скрытые враги сложного процента"},{"id":"b019","markdown":"### Маркетинговые ловушки брокерских интерфейсов\\nБрокерская компания получает основную выручку от двух источников: **комиссий за оборот** и **процентов за пользование маржинальным плечом**. Чем чаще клиент открывает сделки, тем богаче брокер."},{"id":"b020","markdown":"Именно поэтому приложения спроектированы по законам казино:\\n* назойливые push-уведомления (\xabБумага X подорожала на 7% за час!\xbb);\\n* кричащие экраны со списками \xabЛидеры дня\xbb;\\n* подборки спекулятивных \xabинвестидей\xbb от штатных аналитиков."},{"id":"b021","markdown":"Всё это — инструменты цифрового вовлечения, подталкивающие к избыточным действиям."},{"id":"b022","markdown":"**Правило цифровой гигиены:** уберите торговую программу с главного экрана смартфона, заглушите любые ценовые оповещения и установите жёсткий график посещения терминала — **один раз в месяц** для пополнения и **один раз в год** для сверки баланса."},{"id":"b023","markdown":"### Налоговая эрозия капитала\\nФиксация прибыли по сделке моментально превращает 13% от заработанного в обязательство перед бюджетом (НДФЛ). Эти деньги безвозвратно изымаются из базы начисления сложного процента."},{"id":"b024","markdown":"Инвестор, удерживающий активы без продажи годами, сохраняет тело капитала целиком, а при удержании ценных бумаг свыше трёх лет получает право на законное освобождение от налога (льгота на долгосрочное владение — ЛДВ)."},{"id":"b025","markdown":"### Разрушительная сила комиссий за управление (TER)\\nЛюбой эмитент фонда удерживает процент за администрирование. Разница в десятые доли процента на горизонте в четверть века превращается в финансовую пропасть."},{"id":"b026","markdown":"## \uD83E\uDDEE Расчёт на полях тетради: цена одной десятой процента"},{"id":"b027","markdown":"Представим дисциплинированного инвестора, который направляет на фондовый рынок **10 000 ₽ каждый месяц** на протяжении **25 лет** (совокупный объём личных вложений составит **3 000 000 ₽**)."},{"id":"b028","markdown":"Предположим, что базовый индекс приносит **10% годовых** до вычета комиссионных издержек."},{"id":"b029","markdown":"Посмотрим, какой капитал накопится на счёте в зависимости от совокупных расходов фонда (вознаграждение УК, спецдепозитарий, биржевые сборы):"},{"id":"b030","markdown":"| Ежегодная совокупная комиссия | Итоговый капитал через 25 лет | Реальные потери на комиссиях |\\n| :--- | :--- | :--- |\\n| **0,5%** | **~12,3 млн ₽** | Базовый ориентир эффективного фонда |\\n| **1,0%** | **~11,3 млн ₽** | Потеря **1,0 млн ₽** относительно дешёвого фонда |\\n| **2,0%** | **~9,6 млн ₽** | Потеря **2,7 млн ₽** капитала |\\n| **3,0%** | **~8,2 млн ₽** | Потеря **4,1 млн ₽** (больше всех личных взносов!) |"},{"id":"b031","markdown":"```\\nСравнение финансового результата через четверть века:\\n──────────────────────────────────────────────────────────────────\\nСобственные вложения:  3,0 млн ₽\\n──────────────────────────────────────────────────────────────────\\nФонд с комиссией 0,5%: 12,3 млн ₽  ████████████████████████████\\nФонд с комиссией 3,0%:  8,2 млн ₽  ██████████████████\\n──────────────────────────────────────────────────────────────────\\nРазница (упущенная прибыль): 4,1 млн ₽ отдано посредникам!\\n```"},{"id":"b032","markdown":"> ⚠️ Разрыв между качественным биржевым фондом (0,5%) и неэффективным розничным ПИФом (3%) превышает **4 000 000 ₽**. Это сумма, превосходящая все ваши накопления за 25 лет каторжного труда."},{"id":"b033","markdown":"Именно издержки объясняют провал институциональных управляющих: согласно отчётам агентства S&P (исследование SPIVA), к концу 2024 года **89,5% активно управляемых фондов акций США проиграли базовому бенчмарку S&P 500 на 15-летнем треке**. Менеджеры могут профессионально отбирать активы, но бремя внутренних комиссий неизбежно тянет их на дно."},{"id":"b034","markdown":"## 4. Алгоритм пассивного инвестора"},{"id":"b035","markdown":"Для построения антихрупкого портфеля достаточно пяти шагов:"},{"id":"b036","markdown":"1. **Зафиксируйте целевые доли классов активов.** Исходя из горизонта и риск-профиля, распределите портфель (например: 40% — защитная ликвидность и бонды, 60% — долевые активы бизнеса).\\n2. **Используйте биржевые фонды вместо единичных эмитентов.** Сформируйте ядро из 3–4 недорогих инструментов: индекс акций Мосбиржи, корзина надёжных ОФЗ, фонд денежного рынка (LQDT) и инструмент с привязкой к физическому золоту.\\n3. **Настройте регулярный автоплатёж.** Направляйте фиксированную сумму сразу в день получения зарплаты. При снижении котировок вы автоматически покупаете больше паёв по выгодной цене, при росте — меньше. Необходимость угадывать точку входа отпадает.\\n4. **Проводите балансировку раз в 12 месяцев.** Достаточно один раз в год докупить отставшие активы, чтобы вернуть пропорции к целевым значениям.\\n5. **Не прикасайтесь к портфелю в промежутках.** Игнорируйте экономические заголовки и рыночные колебания."},{"id":"b037","markdown":"### Что делать, если непреодолимо тянет поторговать?\\nЕсли вам искренне интересен выбор отдельных акций, выделите под это **песочницу (счёт для хобби)**:\\n* Ограничьте его объём суммой, которую не жалко потратить на экстремальное развлечение вроде прыжка с парашютом (не более 5–10% от накоплений).\\n* Запретите себе докладывать средства на этот счёт в течение года, если депозит сгорит.\\n* Ежегодно сопоставляйте результат своих спекуляций с динамикой классического индексного фонда. Фактические цифры быстро расставят всё по местам."},{"id":"b038","markdown":"## \uD83D\uDCCB Практическое задание"},{"id":"b039","markdown":"1. Зайдите в системные настройки смартфона и полностью **отключите баннеры и уведомления** от брокерских приложений.\\n2. Загрузите брокерский отчёт за прошедший календарный год и выпишите на лист бумаги **точную сумму уплаченных торговых комиссий**.\\n3. Проверьте паспорт каждого фонда в своём портфеле. Если совокупные расходы (TER) превышают **1,2–1,5% в год**, найдите на Мосбирже низкозатратный биржевой аналог."}],"terms":[{"id":"investorskiy-razryv","term":"Инвесторский разрыв (Investor Gap)","definition":"потеря доходности частным лицом из-за попыток угадать пики рынка."},{"id":"komissiya-ter","term":"Комиссия фонда (TER)","definition":"совокупные ежегодные расходы управляющей компании, удерживаемые из стоимости паёв."},{"id":"passivnyj-investor","term":"Пассивный инвестор","definition":"инвестор, приобретающий широкий рынок и удерживающий его без спекуляций."}],"quizzes":[{"id":"q1","q":"По данным регулятора за трёхлетний цикл 2023–2025 гг., средний результат частных лиц на брокерских счетах составил 2,9% годовых, тогда как паи фондов выросли на 17,9%. Что стало главной причиной отставания активных частных инвесторов?","options":["Мосбиржа удерживала повышенную комиссию исключительно со счетов физлиц.","Частные инвесторы массово злоупотребляли деривативами и несвоевременными спекулятивными сделками, в то время как пассивные фонды удерживали активы и зарабатывали на ставке денежного рынка.","Банк России заморозил дивидендные выплаты по брокерским счетам граждан."],"correct":1,"explanation":"Активная спекулятивная торговля инструментами срочного рынка и эмоциональный вход/выход из позиций срезали доходность розничных счетов, тогда как фонды собирали купонный доход и высокую безрисковую премию денежного рынка."},{"id":"q2","q":"Исследования компании Morningstar фиксируют \xabинвесторский разрыв\xbb (Investor Gap), из-за которого клиенты получают в среднем на 1,2 п.п. в год меньше, чем инструмент, в который они вложились. Чем обусловлена эта потеря?","options":["Недобросовестные управляющие намеренно занижают реальную отчётность перед вкладчиками.","Происходит техническое округление котировок при дроблении паёв на бирже.","Инвесторы поддаются жадности и страху: докупают активы после масштабного ралли и панически сбрасывают их после просадки."],"correct":1,"explanation":"Нерациональный поведенческий тайминг заставляет людей заходить на рынок максимальным объёмом на перегретой вершине и выходить в кэш на самом дне падения."},{"id":"q3","q":"Два инвестора ежемесячно инвестируют по 10 000 ₽ на протяжении 25 лет при рыночном росте 10% годовых. Первый выбрал биржевой фонд с комиссией 0,5% в год, второй — розничный ПИФ с издержками 3% в год. Какова разница в итоговом капитале между ними?","options":["Разница составит не более 200 000 ₽, так как 2,5% — незначительная погрешность.","Итоговый капитал будет одинаковым, комиссии удерживаются только при закрытии счёта.","Разница превысит 4 млн ₽ в пользу фонда с низкими издержками, что больше всей суммы их личных пополнений за 25 лет."],"correct":1,"explanation":"Из-за эффекта сложного процента высокий процент за управление съедает свыше 4,1 млн ₽ будущей стоимости капитала, превращая накопления из 12,3 млн ₽ всего в 8,2 млн ₽."}],"officialSources":[]}')}}]);